{"file_text": "@page "/apply"
@rendermode InteractiveServer
@using sv_f97ee5760182446d96f42e73a0d0dff9.Models
@using sv_f97ee5760182446d96f42e73a0d0dff9.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @* ───── Step Indicator Bar ───── *@
    <nav class="d-flex justify-content-between mb-4 position-relative" aria-label="Application steps">
        @for (int i = 0; i < _stepLabels.Length; i++)
        {
            var step = i;
            var status = step < _currentStep ? "completed"
                       : step == _currentStep ? "active"
                       : "upcoming";

            <button type="button"
                    class="btn btn-link text-decoration-none p-0 d-flex flex-column align-items-center step-indicator flex-fill"
                    style="@StepStyle(status)"
                    disabled="@(status == "upcoming")"
                    @onclick="() => GoToStep(step)">
                <span class="rounded-circle d-flex align-items-center justify-content-center mb-1"
                      style="width:36px;height:36px;@StepCircleStyle(status)">
                    @if (status == "completed")
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(step + 1)</span>
                    }
                </span>
                <small style="font-size:.75rem;">@_stepLabels[step]</small>
            </button>
        }
    </nav>

    @* ───── Validation / error banner ───── *@
    @if (!string.IsNullOrEmpty(_error))
    {
        <div class="alert alert-danger py-2">@_error</div>
    }

    @* ───── Step 1: Personal Info ───── *@
    @if (_currentStep == 0)
    {
        <h4>Personal Information</h4>
        <div class="mb-3">
            <label class="form-label">Full Name <span class="text-danger">*</span></label>
            <input class="form-control" @bind="_fullName" />
        </div>
        <div class="mb-3">
            <label class="form-label">Email <span class="text-danger">*</span></label>
            <input type="email" class="form-control" @bind="_email" />
        </div>
        <div class="mb-3">
            <label class="form-label">Phone <span class="text-danger">*</span></label>
            <input type="tel" class="form-control" @bind="_phone" />
        </div>
        <div class="mb-3">
            <label class="form-label">Address <span class="text-danger">*</span></label>
            <textarea class="form-control" rows="2" @bind="_address"></textarea>
        </div>
        <div class="d-flex justify-content-end">
            <button class="btn btn-primary" @onclick="NextFromPersonal" disabled="@_loading">
                @if (_loading) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Next
            </button>
        </div>
    }

    @* ───── Step 2: Work History ───── *@
    @if (_currentStep == 1)
    {
        <h4>Work History</h4>
        @for (int idx = 0; idx < _workEntries.Count; idx++)
        {
            var i = idx;
            var entry = _workEntries[i];
            <div class="card mb-3">
                <div class="card-body">
                    <div class="d-flex justify-content-between align-items-center mb-2">
                        <strong>Position @(i + 1)</strong>
                        @if (_workEntries.Count > 1)
                        {
                            <button class="btn btn-sm btn-outline-danger" @onclick="() => RemoveWorkEntry(i)">Remove</button>
                        }
                    </div>
                    <div class="row g-2 mb-2">
                        <div class="col-md-6">
                            <label class="form-label">Company <span class="text-danger">*</span></label>
                            <input class="form-control" @bind="entry.Company" />
                        </div>
                        <div class="col-md-6">
                            <label class="form-label">Job Title <span class="text-danger">*</span></label>
                            <input class="form-control" @bind="entry.Title" />
                        </div>
                    </div>
                    <div class="row g-2 mb-2">
                        <div class="col-md-4">
                            <label class="form-label">Start Date <span class="text-danger">*</span></label>
                            <input type="date" class="form-control" @bind="entry.StartDate" />
                        </div>
                        <div class="col-md-4">
                            <label class="form-label">End Date</label>
                            <input type="date" class="form-control" @bind="entry.EndDate" disabled="@entry.IsCurrent" />
                        </div>
                        <div class="col-md-4 d-flex align-items-end pb-1">
                            <div class="form-check">
                                <input type="checkbox" class="form-check-input" id="current-@i" @bind="entry.IsCurrent" />
                                <label class="form-check-label" for="current-@i">Currently working here</label>
                            </div>
                        </div>
                    </div>
                    <div class="mb-0">
                        <label class="form-label">Description</label>
                        <textarea class="form-control" rows="2" @bind="entry.Description"></textarea>
                    </div>
                </div>
            </div>
        }
        <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="Back">Back</button>
            <button class="btn btn-primary" @onclick="NextFromWork">Next</button>
        </div>
    }

    @* ───── Step 3: References ───── *@
    @if (_currentStep == 2)
    {
        <h4>References</h4>
        @for (int idx = 0; idx < _references.Count; idx++)
        {
            var i = idx;
            var refEntry = _references[i];
            <div class="card mb-3">
                <div class="card-body">
                    <div class="d-flex justify-content-between align-items-center mb-2">
                        <strong>Reference @(i + 1)</strong>
                        @if (_references.Count > 1)
                        {
                            <button class="btn btn-sm btn-outline-danger" @onclick="() => RemoveReference(i)">Remove</button>
                        }
                    </div>
                    <div class="row g-2 mb-2">
                        <div class="col-md-6">
                            <label class="form-label">Name <span class="text-danger">*</span></label>
                            <input class="form-control" @bind="refEntry.Name" />
                        </div>
                        <div class="col-md-6">
                            <label class="form-label">Relationship <span class="text-danger">*</span></label>
                            <input class="form-control" @bind="refEntry.Relationship" />
                        </div>
                    </div>
                    <div class="row g-2">
                        <div class="col-md-6">
                            <label class="form-label">Email <span class="text-danger">*</span></label>
                            <input type="email" class="form-control" @bind="refEntry.Email" />
                        </div>
                        <div class="col-md-6">
                            <label class="form-label">Phone <span class="text-danger">*</span></label>
                            <input type="tel" class="form-control" @bind="refEntry.Phone" />
                        </div>
                    </div>
                </div>
            </div>
        }
        @if (_references.Count < 3)
        {
            <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
        }
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="Back">Back</button>
            <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
        </div>
    }

    @* ───── Step 4: Cover Letter ───── *@
    @if (_currentStep == 3)
    {
        <h4>Cover Letter</h4>
        <div class="mb-2">
            <textarea class="form-control" rows="10" maxlength="2000"
                      @bind="_coverLetter" @bind:event="oninput"></textarea>
        </div>
        <div class="text-muted mb-3">@(_coverLetter?.Length ?? 0) / 2000 characters</div>
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="Back">Back</button>
            <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next</button>
        </div>
    }

    @* ───── Step 5: Review & Submit ───── *@
    @if (_currentStep == 4)
    {
        @if (_submitted)
        {
            <div class="text-center py-5">
                <h3 class="text-success">&#10003; Application Submitted!</h3>
                <p class="lead">Your application ID is <strong>@_applicationId</strong>.</p>
                <p>We will review your application and get back to you soon.</p>
            </div>
        }
        else
        {
            <h4>Review &amp; Submit</h4>

            @* Personal Info *@
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>Personal Information</strong>
                    <button class="btn btn-sm btn-link" @onclick="() => GoToStep(0)">Edit</button>
                </div>
                <div class="card-body">
                    <p class="mb-1"><strong>Name:</strong> @_fullName</p>
                    <p class="mb-1"><strong>Email:</strong> @_email</p>
                    <p class="mb-1"><strong>Phone:</strong> @_phone</p>
                    <p class="mb-0"><strong>Address:</strong> @_address</p>
                </div>
            </div>

            @* Work History *@
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>Work History</strong>
                    <button class="btn btn-sm btn-link" @onclick="() => GoToStep(1)">Edit</button>
                </div>
                <div class="card-body">
                    @foreach (var entry in _workEntries)
                    {
                        <div class="mb-2 pb-2 border-bottom">
                            <p class="mb-1"><strong>@entry.Title</strong> at @entry.Company</p>
                            <p class="mb-1 text-muted">
                                @entry.StartDate.ToString("MMM yyyy") &ndash;
                                @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                            </p>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p class="mb-0">@entry.Description</p>
                            }
                        </div>
                    }
                </div>
            </div>

            @* References *@
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>References</strong>
                    <button class="btn btn-sm btn-link" @onclick="() => GoToStep(2)">Edit</button>
                </div>
                <div class="card-body">
                    @foreach (var r in _references)
                    {
                        <div class="mb-2 pb-2 border-bottom">
                            <p class="mb-1"><strong>@r.Name</strong> (@r.Relationship)</p>
                            <p class="mb-0 text-muted">@r.Email &bull; @r.Phone</p>
                        </div>
                    }
                </div>
            </div>

            @* Cover Letter *@
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>Cover Letter</strong>
                    <button class="btn btn-sm btn-link" @onclick="() => GoToStep(3)">Edit</button>
                </div>
                <div class="card-body">
                    <p style="white-space: pre-wrap;">@_coverLetter</p>
                </div>
            </div>

            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="Back">Back</button>
                <button class="btn btn-success btn-lg" @onclick="Submit" disabled="@_loading">
                    @if (_loading) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Submit Application
                </button>
            </div>
        }
    }
</div>

