                    <strong>Work History</strong>
                    <button class="btn btn-sm btn-link" @onclick="() => GoToStep(1)">Edit</button>
                </div>
                <div class="card-body">
                    @foreach (var entry in _workEntries)
                    {
                        <div class="mb-2 pb-2 border-bottom">
                            <p class="mb-1"><strong>@entry.Title</strong> at @entry.Company</p>
                            <p class="mb-1 text-muted">
                                @entry.StartDate.ToString("MMM yyyy") &ndash;
                                @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                            </p>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p class="mb-0">@entry.Description</p>
                            }
                        </div>
                    }
                </div>
            </div>

            @* References *@
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>References</strong>
                    <button class="btn btn-sm btn-link" @onclick="() => GoToStep(2)">Edit</button>
                </div>
                <div class="card-body">
                    @foreach (var r in _references)
                    {
                        <div class="mb-2 pb-2 border-bottom">
                            <p class="mb-1"><strong>@r.Name</strong> (@r.Relationship)</p>
                            <p class="mb-0 text-muted">@r.Email &bull; @r.Phone</p>
                        </div>
                    }
                </div>
            </div>

            @* Cover Letter *@
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>Cover Letter</strong>
                    <button class="btn btn-sm btn-link" @onclick="() => GoToStep(3)">Edit</button>
                </div>
                <div class="card-body">
                    <p style="white-space: pre-wrap;">@_coverLetter</p>
                </div>
            </div>

            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="Back">Back</button>
                <button class="btn btn-success btn-lg" @onclick="Submit" disabled="@_loading">
                    @if (_loading) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Submit Application
                </button>
            </div>
        }
    }
</div>

@code {
    private static readonly string[] _stepLabels =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    private int _currentStep;
    private string? _error;
    private bool _loading;
    private bool _submitted;
    private int _applicationId;

    // Step 1
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2
    private List<WorkEntryModel> _workEntries = [new()];

    // Step 3
    private List<ReferenceModel> _references = [new()];

    // Step 4
    private string _coverLetter = "";

    // ── Navigation ──

    private void GoToStep(int step)
    {
        if (step < _currentStep)
        {
            _error = null;
            _currentStep = step;
        }
    }

    private void Back()
    {
        _error = null;
        _currentStep--;
    }

    // ── Step 1 validation ──

    private async Task NextFromPersonal()
    {
        _error = null;

        if (string.IsNullOrWhiteSpace(_fullName) ||
            string.IsNullOrWhiteSpace(_email) ||
            string.IsNullOrWhiteSpace(_phone) ||
            string.IsNullOrWhiteSpace(_address))
        {
            _error = "Please fill in all required fields.";
            return;
        }

        _loading = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(_email);
            if (!emailValid)
            {
                _error = "Please enter a valid email address.";
                return;
            }
            _currentStep = 1;
        }
        finally
        {
            _loading = false;
        }
    }

    // ── Step 2 validation ──

    private void NextFromWork()
    {
        _error = null;

        foreach (var entry in _workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) ||
                string.IsNullOrWhiteSpace(entry.Title) ||
                entry.StartDate == default)
            {
                _error = "Please fill in company, title, and start date for each position.";
                return;
            }
        }
        _currentStep = 2;
    }

    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index) => _workEntries.RemoveAt(index);

    // ── Step 3 validation ──

    private void NextFromReferences()
    {
        _error = null;

        foreach (var r in _references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) ||
                string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) ||
                string.IsNullOrWhiteSpace(r.Phone))
            {
                _error = "Please fill in all fields for each reference.";
                return;
            }
        }
        _currentStep = 3;
    }

    private void AddReference() { if (_references.Count < 3) _references.Add(new ReferenceModel()); }
    private void RemoveReference(int index) => _references.RemoveAt(index);

    // ── Step 4 ──

    private void NextFromCoverLetter()
    {
        _error = null;
        _currentStep = 4;
    }

    // ── Submit ──

    private async Task Submit()
    {
        _error = null;
        _loading = true;
        try
        {
            var application = new JobApplication(
                new PersonalInfo(_fullName, _email, _phone, _address),
                new WorkHistory(_workEntries.Select(e =>
                    new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description ?? "")
                ).ToList()),
                _references.Select(r =>
                    new Reference(r.Name, r.Relationship, r.Email, r.Phone)
                ).ToList(),
                _coverLetter ?? ""
            );

            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch
        {
            _error = "An error occurred while submitting. Please try again.";
        }
        finally
        {
            _loading = false;
        }
    }

    // ── Styling helpers ──

    private static string StepStyle(string status) => status switch
    {
        "completed" => "color: #198754; cursor: pointer;",
        "active" => "color: #0d6efd; cursor: default;",
        _ => "color: #adb5bd; cursor: default;"
    };

    private static string StepCircleStyle(string status) => status switch
    {
        "completed" => "background: #198754; color: white; font-weight: bold;",
        "active" => "background: #0d6efd; color: white; font-weight: bold;",
        _ => "background: #e9ecef; color: #adb5bd;"
    };

    // ── Mutable view-models for form binding ──

    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string? Description { get; set; }
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

